58	    /**
59	     * Add a claim for a person on the sheet; with no date it is dated the sheet's today. Refused when
60	     * it is dated inside a closed period, or when it is a correction that does not name a SETTLED claim
61	     * of the same person (see {@link #refuseUnlessCorrects}).
62	     */
63	    @Transactional
64	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
65	            String corrects) {
66	        Rollups.Rollup before = rollups.take(sheetId);
67	        Person person = person(sheetId, personId);
68	        LocalDate dated = date != null ? date : sheets.today(sheetId);
69	        LocalDate dueBy = dueBy(sheets.lock(sheetId), person, dated);
70	        periods.refuseIfClosed(sheetId, dated);
71	        refuseIfRetired(person, dated);
72	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
73	        Claim claim = claims.saveAndFlush(new Claim(sheetId, personId, money(amount), dated, dueBy, clean(note), corrects));
74	        claim = logged(claim, user, person);
75	        audited("CLAIM_ADDED", sheetId, user, person, claim);
76	        rollups.audit(sheetId, user, before);
77	        return claim;
78	    }
79	
80	    /**
81	     * Change a claim's amount, date, note and the number it corrects; with no date it keeps its own. Only a DRAFT claim can be
82	     * edited: an OPEN one is changed by voiding it and adding a new one. Refused when the claim, or the
83	     * date it moves to, is inside a closed period, or when it would be a correction that does not name a
84	     * SETTLED claim of the same person.
85	     */
86	    @Transactional
87	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
88	            String corrects) {
89	        Rollups.Rollup before = rollups.take(sheetId);
90	        sheets.lock(sheetId);
91	        Claim claim = claim(sheetId, claimId);
92	        if (claim.getStatus() != ClaimStatus.DRAFT) {
93	            throw new ResponseStatusException(HttpStatus.CONFLICT,
94	                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
95	        }
96	        periods.refuseIfClosed(sheetId, claim.getDate());
97	        if (date != null) {
98	            periods.refuseIfClosed(sheetId, date);
99	            refuseIfRetired(person(sheetId, claim.getPersonId()), date);
100	        }
101	        refuseUnlessCorrects(sheetId, claim.getPersonId(), amount, corrects);
102	        claim.change(money(amount), date != null ? date : claim.getDate(), clean(note), corrects);
103	        Claim saved = claims.saveAndFlush(claim);
104	        audited("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved);
105	        rollups.audit(sheetId, user, before);
106	        return saved;
107	    }
108	
109	    /**
110	     * Move a claim to a new status, recording the event; refused (and nothing written) when the
111	     * claim's current status does not allow the move. Settling fixes the claim's due at the rate
112	     * the person's grade has in force on the claim's date, or at the figure a statement bound it to,
113	     * with the late charge it has then frozen in.
114	     * Opening numbers the claim and records who opened it; a voided claim keeps its number, which
115	     * is never reused. The user who opened a claim
116	     * is refused when settling it. A clerk settling a claim whose due is above the sheet's clerk limit
117	     * (a due of n/a is within any limit) sends it PENDING instead, for a steward to approve or reject;
118	     * a steward settles any. A move the sheet's permission matrix does not allow the user's role is
119	     * refused. A claim dated inside a closed period cannot be moved, nor can a claim
120	     * deferred on the sheet's today be settled. A SETTLED claim is voided only by a steward, within
121	     * {@link ClaimStatus#VOID_SETTLED_DAYS} days of its settlement; its frozen figure leaves every
122	     * total and the audit records it as reversed.
123	     */
124	    @Transactional
125	    public Claim move(String sheetId, String user, long claimId, ClaimStatus next) {
126	        // Every move takes the sheet's lock before reading the claim, so concurrent opens on the
127	        // sheet are serialised: each sees the other's committed claim and number.
128	        LocalDate today = sheets.lock(sheetId).getToday();
129	        Rollups.Rollup before = rollups.take(sheetId);
130	        Claim claim = claim(sheetId, claimId);
131	        periods.refuseIfClosed(sheetId, claim.getDate());
132	        String action = switch (next) {
133	            case OPEN -> "open";
134	            case SETTLED -> "settle";
135	            case VOID -> "void";
136	            case PENDING, DRAFT -> throw new IllegalArgumentException("No move to " + next + ".");
137	        };
138	        if (!roles.permits(sheetId, user, action)) {
139	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim.");
140	        }
141	        if (!claim.getStatus().canBecome(next)) {
142	            throw new ResponseStatusException(HttpStatus.CONFLICT,
143	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
144	        }
145	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
146	        if (voidingSettled) {
147	            refuseVoidingSettled(sheetId, user, claim, today);
148	        }
149	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(today)) {
150	            throw new ResponseStatusException(HttpStatus.CONFLICT,
151	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be settled before then.");
152	        }
153	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
154	            throw new ResponseStatusException(HttpStatus.CONFLICT,
155	                    "The user who opened a claim cannot settle it.");
156	        }
157	        Person person = person(sheetId, claim.getPersonId());
158	        BigDecimal settledDue = next == ClaimStatus.SETTLED
159	                ? dues.settling(claim, person.gradeOn(claim.getDate()))
160	                : null;
161	        if (next == ClaimStatus.SETTLED) {
162	            refuseUnproved(sheetId, claim, settledDue);
163	        }
164	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settledDue)) {
165	            next = ClaimStatus.PENDING;
166	            settledDue = null;
167	        }
168	        claim.become(next);
169	        if (next == ClaimStatus.OPEN) {
170	            claim.number(periods.nextClaimNumber(sheetId, claim.getDate()));
171	            claim.openedBy(user);
172	        }
173	        if (next == ClaimStatus.SETTLED) {
174	            claim.settleDue(settledDue);
175	        }
176	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
177	        String event = switch (next) {
178	            case OPEN -> "CLAIM_OPENED";
179	            case SETTLED -> "CLAIM_SETTLED";
180	            case PENDING -> "CLAIM_PENDING";
181	            case VOID -> "CLAIM_VOIDED";
182	            case DRAFT -> throw new IllegalStateException();
183	        };
184	        String suffix = next == ClaimStatus.SETTLED
185	                ? " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
186	                : voidingSettled
187	                ? " reversed=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
188	                : "";
189	        audited(event, sheetId, user, person, saved, saved.getNumber(), suffix);
190	        if (next == ClaimStatus.SETTLED) {
191	            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
192	        }
193	        rollups.audit(sheetId, user, before);
194	        return saved;
195	    }
