197	    /** Raise a claim's proofs count by one; refused when the claim is SETTLED or VOID. */
198	    @Transactional
199	    public Claim addProof(String sheetId, String user, long claimId) {
200	        sheets.lock(sheetId);
201	        Claim claim = claim(sheetId, claimId);
202	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
203	            throw new ResponseStatusException(HttpStatus.CONFLICT,
204	                    "A " + claim.getStatus() + " claim cannot take a proof.");
205	        }
206	        claim.addProof();
207	        Claim saved = claims.saveAndFlush(claim);
208	        audited("CLAIM_PROOF_ADDED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
209	                " proofs=" + saved.getProofs());
210	        return saved;
211	    }
