213	    /**
214	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it,
215	     * the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
216	     * statement. Refused when the claim is not OPEN, when the date is not after the sheet's today, or
217	     * when the claim is dated inside a closed period.
218	     */
219	    @Transactional
220	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
221	        LocalDate today = sheets.lock(sheetId).getToday();
222	        Rollups.Rollup before = rollups.take(sheetId);
223	        Claim claim = claim(sheetId, claimId);
224	        if (claim.getStatus() != ClaimStatus.OPEN) {
225	            throw new ResponseStatusException(HttpStatus.CONFLICT,
226	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can.");
227	        }
228	        if (!until.isAfter(today)) {
229	            throw new ResponseStatusException(HttpStatus.CONFLICT,
230	                    "A claim can only be deferred to a date after the sheet's today, " + today + ".");
231	        }
232	        periods.refuseIfClosed(sheetId, claim.getDate());
233	        claim.defer(until);
234	        Claim saved = claims.saveAndFlush(claim);
235	        audited("CLAIM_DEFERRED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
236	                " until=" + until);
237	        rollups.audit(sheetId, user, before);
238	        return saved;
239	    }
240	
241	    /**
242	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at this moment at its live figure with
243	     * the late charge it has then. Only a steward approves, and not the user who opened the claim.
244	     */
245	    @Transactional
246	    public Claim approve(String sheetId, String user, long claimId) {
247	        sheets.lock(sheetId);
248	        Rollups.Rollup before = rollups.take(sheetId);
249	        Claim claim = pending(sheetId, user, claimId);
250	        if (user.equals(claim.getOpenedBy())) {
251	            throw new ResponseStatusException(HttpStatus.CONFLICT,
252	                    "The user who opened a claim cannot approve it.");
253	        }
254	        Person person = person(sheetId, claim.getPersonId());
255	        BigDecimal approvedDue = dues.approving(claim, person.gradeOn(claim.getDate()));
256	        refuseUnproved(sheetId, claim, approvedDue);
257	        claim.settleDue(approvedDue);
258	        claim.become(ClaimStatus.SETTLED);
259	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
260	        audited("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber(),
261	                " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE));
262	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
263	        rollups.audit(sheetId, user, before);
264	        return saved;
265	    }
266	
267	    /**
268	     * Re-settle a SETTLED claim: its due is fixed again at the figure it would have today as an OPEN
269	     * claim bound by no statement (today's rates, grades, floor and late charge). Only a steward
270	     * re-settles; refused when the claim is not SETTLED or is dated inside a closed period.
271	     */
272	    @Transactional
273	    public Claim resettle(String sheetId, String user, long claimId) {
274	        sheets.lock(sheetId);
275	        Rollups.Rollup before = rollups.take(sheetId);
276	        Claim claim = claim(sheetId, claimId);
277	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
278	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
279	        }
280	        if (claim.getStatus() != ClaimStatus.SETTLED) {
281	            throw new ResponseStatusException(HttpStatus.CONFLICT,
282	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
283	        }
284	        periods.refuseIfClosed(sheetId, claim.getDate());
285	        Person person = person(sheetId, claim.getPersonId());
286	        BigDecimal old = claim.getSettledDue();
287	        claim.settleDue(dues.resettling(claim, person.gradeOn(claim.getDate())));
288	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
289	        audited("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
290	                " old=" + (old != null ? old.toPlainString() : NO_RATE)
291	                        + " new=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE));
292	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
293	        rollups.audit(sheetId, user, before);
294	        return saved;
295	    }
296	
297	    /**
298	     * Reject a PENDING claim with a reason: it is OPEN again, bound again by its person's last
299	     * statement when that statement included it. Only a steward rejects.
300	     */
301	    @Transactional
302	    public Claim reject(String sheetId, String user, long claimId, String reason) {
303	        sheets.lock(sheetId);
304	        Rollups.Rollup before = rollups.take(sheetId);
305	        Claim claim = pending(sheetId, user, claimId);
306	        claim.become(ClaimStatus.OPEN);
307	        Claim saved = logged(claims.saveAndFlush(claim), user, person(sheetId, claim.getPersonId()));
308	        audited("CLAIM_REJECTED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
309	                " reason=" + reason.trim());
310	        rollups.audit(sheetId, user, before);
311	        return saved;
312	    }
313	
314	    /**
315	     * Move a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its number and
316	     * date, and loses any figure a statement bound it to, its due live again until its new person's
317	     * next statement. Only a role the sheet's permission matrix allows (a steward by
318	     * default) reassigns. Refused when the claim is SETTLED or VOID, when it is
319	     * dated inside a closed period, when the new person is its own, is retired before its date, or (for
320	     * a correction) has no SETTLED claim of the number it corrects.
321	     */
322	    @Transactional
323	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
324	        sheets.lock(sheetId);
325	        Rollups.Rollup before = rollups.take(sheetId);
326	        Claim claim = claim(sheetId, claimId);
327	        if (!roles.permits(sheetId, user, "reassign")) {
328	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim.");
329	        }
330	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
331	            throw new ResponseStatusException(HttpStatus.CONFLICT,
332	                    "A " + claim.getStatus() + " claim cannot be reassigned.");
333	        }
334	        periods.refuseIfClosed(sheetId, claim.getDate());
335	        Person from = person(sheetId, claim.getPersonId());
336	        Person to = person(sheetId, personId);
337	        if (from.getId().equals(to.getId())) {
338	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
339	        }
340	        refuseIfRetired(to, claim.getDate());
341	        refuseUnlessCorrects(sheetId, personId, claim.getAmount(), claim.getCorrects());
342	        claim.reassign(to.getId());
343	        claim.unbind();
344	        Claim saved = claims.saveAndFlush(claim);
345	        audited("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
346	                " from=" + from.getName() + " to=" + to.getName());
347	        rollups.audit(sheetId, user, before);
348	        return saved;
349	    }
350	
351	    /** What a split did: the original claim, as it is now, and the new claim split off it. */
352	    public record Split(Claim original, Claim split) {
353	    }
354	
355	    /**
356	     * Split an amount (above 0.00 and below the claim's amount) off an OPEN claim: it keeps the rest
357	     * of its amount and loses any figure a statement bound it to; a new OPEN claim with the split-off
358	     * amount, the same date and note, the next number, opened by the user and due by a date fixed now
359	     * from the terms in force on its date, names the original's number as the one it was split from.
360	     * Refused when the claim is not OPEN, is deferred on the sheet's today, or is dated inside a
361	     * closed period.
362	     */
363	    @Transactional
364	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
365	        Sheet sheet = sheets.lock(sheetId);
366	        LocalDate today = sheet.getToday();
367	        Rollups.Rollup before = rollups.take(sheetId);
368	        Claim claim = claim(sheetId, claimId);
369	        if (claim.getStatus() != ClaimStatus.OPEN) {
370	            throw new ResponseStatusException(HttpStatus.CONFLICT,
371	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can.");
372	        }
373	        if (claim.isDeferredOn(today)) {
374	            throw new ResponseStatusException(HttpStatus.CONFLICT,
375	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be split.");
376	        }
377	        periods.refuseIfClosed(sheetId, claim.getDate());
378	        BigDecimal off = money(amount);
379	        if (off.signum() <= 0 || off.compareTo(claim.getAmount()) >= 0) {
380	            throw new ResponseStatusException(HttpStatus.CONFLICT,
381	                    "The amount split off must be above 0.00 and below the claim's " + claim.getAmount().toPlainString() + ".");
382	        }
383	        Person person = person(sheetId, claim.getPersonId());
384	        LocalDate dueBy = dueBy(sheet, person, claim.getDate());
385	        Claim split = claim.split(off, dueBy);
386	        split.number(periods.nextClaimNumber(sheetId, split.getDate()));
387	        split.openedBy(user);
388	        Claim original = claims.saveAndFlush(claim);
389	        split = logged(claims.saveAndFlush(split), user, person);
390	        audited("CLAIM_SPLIT", sheetId, user, person, original, original.getNumber(), " into=" + split.getNumber());
391	        audited("CLAIM_OPENED", sheetId, user, person, split);
392	        rollups.audit(sheetId, user, before);
393	        return new Split(original, split);
394	    }
395	
396	    /**
397	     * The PENDING claim a steward approves or rejects; refused when it is not PENDING, when its date
398	     * is inside a closed period, or when the user is not a steward.
399	     */
400	    private Claim pending(String sheetId, String user, long claimId) {
401	        Claim claim = claim(sheetId, claimId);
402	        periods.refuseIfClosed(sheetId, claim.getDate());
403	        if (claim.getStatus() != ClaimStatus.PENDING) {
404	            throw new ResponseStatusException(HttpStatus.CONFLICT,
405	                    "A " + claim.getStatus() + " claim is not pending approval.");
406	        }
407	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
408	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
409	        }
410	        return claim;
411	    }
412	
413	    /**
414	     * Refuse settling or approving a claim with no proofs whose due is above the sheet's proof threshold
415	     * in force on the claim's date (a due of n/a is within any threshold).
416	     */
417	    private void refuseUnproved(String sheetId, Claim claim, BigDecimal due) {
418	        BigDecimal threshold = sheets.load(sheetId).proofThresholdOn(claim.getDate());
419	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
420	            throw new ResponseStatusException(HttpStatus.CONFLICT,
421	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
422	                            + ": it needs a proof before it is settled.");
423	        }
424	    }
425	
426	    /**
427	     * Refuse voiding a SETTLED claim unless the user acts as a steward and the sheet's today is no more
428	     * than {@link ClaimStatus#VOID_SETTLED_DAYS} days after the claim's settlement in its status log.
429	     */
430	    private void refuseVoidingSettled(String sheetId, String user, Claim claim, LocalDate today) {
431	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
432	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a SETTLED claim.");
433	        }
434	        LocalDate settledOn = claim.settledOn();
435	        if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(ClaimStatus.VOID_SETTLED_DAYS))) {
436	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can only be voided within "
437	                    + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement.");
438	        }
439	    }
440	
441	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit. */
442	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
443	        BigDecimal limit = sheets.clerkLimit(sheetId);
444	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
445	            return false;
446	        }
447	        return Role.CLERK.equals(roles.roleOf(sheetId, user));
448	    }
449	
450	    /**
451	     * Refuse a correction (an amount below 0.00) unless it names, by number, a SETTLED claim of the
452	     * same person; and refuse naming a claim to correct on any other claim.
453	     */
454	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
455	        if (amount.signum() >= 0) {
456	            if (corrects != null) {
457	                throw new ResponseStatusException(HttpStatus.CONFLICT,
458	                        "Only a correction, with an amount below 0.00, names a claim it corrects.");
459	            }
460	            return;
461	        }
462	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
463	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
464	                .isPresent();
465	        if (!settled) {
466	            throw new ResponseStatusException(HttpStatus.CONFLICT,
467	                    "A correction must name the number of a SETTLED claim of the same person.");
468	        }
469	    }
470	
471	    /** Refuse a claim dated after its person's retirement. */
472	    private static void refuseIfRetired(Person person, LocalDate date) {
473	        if (!person.canClaimOn(date)) {
474	            throw new ResponseStatusException(HttpStatus.CONFLICT,
475	                    person.getName() + " is retired from " + person.getRetiredFrom() + ": a claim cannot be dated after it.");
476	        }
477	    }
478	
479	    private Claim claim(String sheetId, long claimId) {
480	        return claims.findByIdAndSheetId(claimId, sheetId)
481	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
482	    }
483	
484	    /**
485	     * The date a claim of the person dated on a date is due by: its date plus the first of the
486	     * person's own terms, their grade's terms and the sheet's terms in force on it.
487	     */
488	    private static LocalDate dueBy(Sheet sheet, Person person, LocalDate date) {
489	        Integer own = person.getTerms();
490	        return date.plusDays(own != null ? own : sheet.termsFor(person.gradeOn(date), date));
491	    }
492	
493	    private Person person(String sheetId, long personId) {
494	        return people.findByIdAndSheetId(personId, sheetId)
495	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
496	    }
497	
498	    /**
499	     * Add a line to the claim's status log for the status it now has: by the user, on the sheet's
500	     * today, with its due as computed now.
501	     */
502	    private Claim logged(Claim claim, String user, Person person) {
503	        claim.logged(user, sheets.today(claim.getSheetId()), dues.due(claim, person.gradeOn(claim.getDate())));
504	        return claims.saveAndFlush(claim);
